mapper.select:
SELECT j.id, j.enterprise_id, e.enterprise_name, j.category_id, jc.category_name, j.job_name, j.job_description, j.required_major, j.required_skills, j.required_education, j.required_experience, j.work_location, j.salary_min, j.salary_max, j.salary_type, j.job_type, j.recruit_count, j.view_count, j.apply_count, j.publish_time, j.expire_time, j.create_time, CASE WHEN jf.id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, CASE WHEN ja.id IS NOT NULL THEN 1 ELSE 0 END AS is_applied FROM job j LEFT JOIN enterprise e ON j.enterprise_id = e.id LEFT JOIN job_category jc ON j.category_id = jc.id LEFT JOIN job_favorite jf ON j.id = jf.job_id
AND jf.student_id = #{studentId}
LEFT JOIN job_application ja ON j.id = ja.job_id
AND ja.student_id = #{studentId}
WHERE j.id = #{jobId} AND j.status = 1 AND (j.expire_time IS NULL OR j.expire_time > NOW())

SELECT j.id, j.enterprise_id, e.enterprise_name, j.job_name, j.work_location, j.salary_min, j.salary_max, j.salary_type, j.job_type, j.recruit_count, j.view_count, j.apply_count, j.publish_time, j.create_time, CASE WHEN jf.id IS NOT NULL THEN 1 ELSE 0 END AS is_favorite, ROUND( LEAST(100, (CASE WHEN s.major IS NOT NULL AND j.required_major IS NOT NULL AND j.required_major LIKE CONCAT('%', s.major, '%') THEN 35 ELSE 0 END) + (CASE WHEN s.skills IS NOT NULL AND j.required_skills IS NOT NULL AND ( j.required_skills LIKE CONCAT('%', s.skills, '%') OR s.skills LIKE CONCAT('%', j.required_skills, '%') ) THEN 35 ELSE 0 END) + (CASE WHEN s.expected_location IS NOT NULL AND j.work_location LIKE CONCAT('%', s.expected_location, '%') THEN 20 ELSE 0 END) + (CASE WHEN j.publish_time >= DATE_SUB(NOW(), INTERVAL 14 DAY) THEN 10 ELSE 0 END) ), 0 ) AS match_score FROM job j LEFT JOIN enterprise e ON j.enterprise_id = e.id LEFT JOIN job_favorite jf ON j.id = jf.job_id AND jf.student_id = #{studentId} LEFT JOIN student s ON s.id = #{studentId}
j.status = 1 AND (j.expire_time IS NULL OR j.expire_time > NOW())
ORDER BY match_score DESC, j.publish_time DESC LIMIT #{limit}
